// src/pages/Dashboard.js - FIXED VERSION
import React, { useState, useEffect } from "react";
import {
  auth,
  signOut,
  getIdToken,
  db,
  collection,
  addDoc,
  query,
  where,
  getDocs,
  orderBy,
  serverTimestamp,
} from "../firebase";

import {
  Github,
  Sparkles,
  Copy,
  Download,
  Star,
  GitFork,
  Clock,
  GitBranch,
} from "lucide-react";

const Dashboard = ({ user }) => {
  const [formData, setFormData] = useState({
    github_url: "",
    num_points: 5,
    technical_level: "medium",
    output_tone: "action-oriented",
    generate_technical: true,
    branch: "",
  });

  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [branches, setBranches] = useState([]);
  const [loadingBranches, setLoadingBranches] = useState(false);
  const [history, setHistory] = useState([]);
  const [historyLoading, setHistoryLoading] = useState(false);

  // Load history from Firestore on mount - FIXED VERSION
  useEffect(() => {
    if (!user) {
      console.log("No user found, skipping history fetch");
      return;
    }

    const fetchHistory = async () => {
      console.log("Fetching history for user:", user.uid);
      setHistoryLoading(true);

      try {
        // Debug: Log Firebase config
        console.log("Firebase config check:", {
          userId: user.uid,
          userEmail: user.email,
          dbInstance: db ? "✅ Connected" : "❌ Not connected"
        });

        const historyQuery = query(
          collection(db, "repo_histories"),
          where("uid", "==", user.uid),
          orderBy("timestamp", "desc")
        );

        console.log("Query created successfully");

        const snapshot = await getDocs(historyQuery);
        console.log("Query executed successfully, docs found:", snapshot.size);

        const histories = [];
        snapshot.forEach((doc) => {
          const data = doc.data();
          console.log("Document data:", data);
          histories.push({ 
            id: doc.id, 
            ...data,
            // Convert Firestore timestamp to JavaScript Date if needed
            timestamp: data.timestamp?.toDate ? data.timestamp.toDate() : data.timestamp
          });
        });

        setHistory(histories);
        console.log("History loaded successfully:", histories.length, "items");

      } catch (err) {
        console.error("Detailed fetch history error:", err);
        console.error("Error code:", err.code);
        console.error("Error message:", err.message);

        // Handle specific Firebase errors
        if (err.code === 'permission-denied') {
          setError("Permission denied. Please check Firestore security rules.");
        } else if (err.code === 'failed-precondition') {
          setError("Database index missing. Please create required indexes in Firebase Console.");
        } else if (err.code === 'unavailable') {
          setError("Firebase service temporarily unavailable. Please try again.");
        } else {
          setError(`Failed to fetch history: ${err.message}`);
        }
      } finally {
        setHistoryLoading(false);
      }
    };

    // Add a small delay to ensure auth is fully loaded
    const timer = setTimeout(() => {
      fetchHistory();
    }, 500);

    return () => clearTimeout(timer);
  }, [user]);

  // Logout handler
  const handleLogout = async () => {
    try {
      await signOut(auth);
      console.log("User signed out successfully");
    } catch (error) {
      console.error("Logout error:", error);
      setError(`Logout failed: ${error.message}`);
    }
  };

  const handleInputChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: type === "checkbox" ? checked : value,
    }));
  };

  // Fetch branches for branch selection dropdown - ENHANCED VERSION
  const fetchBranches = async (githubUrl) => {
    if (!githubUrl) return;

    try {
      const urlParts = githubUrl.split("/").filter(Boolean);
      if (urlParts.length < 2) return;

      const owner = urlParts[urlParts.length - 2];
      const repo = urlParts[urlParts.length - 1];

      setLoadingBranches(true);

      // Get user token for authenticated requests
      const token = await getIdToken(user);
      console.log("Fetching branches for:", owner, "/", repo);

      const response = await fetch(
        `http://localhost:8000/get-branches/${owner}/${repo}`,
        {
          headers: {
            Authorization: `Bearer ${token}`,
            'Content-Type': 'application/json',
          },
        }
      );

      if (response.ok) {
        const data = await response.json();
        console.log("Branches fetched:", data.branches);
        setBranches(data.branches || []);
        setFormData((prev) => ({ ...prev, branch: "" }));
      } else {
        console.error("Failed to fetch branches:", response.status, response.statusText);
        const errorText = await response.text();
        console.error("Error response:", errorText);
        setBranches([]);
      }
    } catch (err) {
      console.error("Error fetching branches:", err);
      setBranches([]);
    } finally {
      setLoadingBranches(false);
    }
  };

  const handleUrlBlur = () => {
    if (formData.github_url) {
      fetchBranches(formData.github_url);
    }
  };

  // Submit form and generate resume points - ENHANCED VERSION
  const handleSubmit = async () => {
    setLoading(true);
    setError("");
    setResult(null);

    try {
      console.log("Starting resume generation for user:", user.uid);

      const token = await getIdToken(user);
      console.log("Got user token");

      let requestData = {
        ...formData,
        num_points: parseInt(formData.num_points, 10),
      };

      if (!requestData.branch) {
        delete requestData.branch;
      }

      console.log("Request data:", requestData);

      const response = await fetch("http://localhost:8000/generate-resume-points", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(requestData),
      });

      console.log("API response status:", response.status);

      if (!response.ok) {
        const errorData = await response.json();
        console.error("API error response:", errorData);
        throw new Error(
          errorData.error || errorData.detail || "Failed to generate resume points"
        );
      }

      const data = await response.json();
      console.log("Resume points generated successfully:", data);
      setResult(data);

      // Save this request to history - ENHANCED VERSION
      try {
        console.log("Saving to Firestore...");

        const historyData = {
          uid: user.uid,
          userEmail: user.email || null,
          github_url: formData.github_url,
          branch: formData.branch || null,
          points: data.points,
          repository_info: data.repository_info,
          settings: {
            num_points: formData.num_points,
            technical_level: formData.technical_level,
            output_tone: formData.output_tone,
            generate_technical: formData.generate_technical
          },
          timestamp: serverTimestamp(),
          created_at: new Date().toISOString() // Backup timestamp
        };

        console.log("Data to save:", historyData);

        const docRef = await addDoc(collection(db, "repo_histories"), historyData);
        console.log("Saved to Firestore with ID:", docRef.id);

        // Add to local history state immediately
        const newHistoryEntry = {
          id: docRef.id,
          ...historyData,
          timestamp: new Date() // Use current date for immediate display
        };

        setHistory((prev) => [newHistoryEntry, ...prev]);

      } catch (saveError) {
        console.error("Failed to save to Firestore:", saveError);
        console.error("Save error code:", saveError.code);
        console.error("Save error message:", saveError.message);

        // Don't fail the whole operation if saving fails
        setError(`Resume generated successfully, but failed to save to history: ${saveError.message}`);
      }

    } catch (err) {
      console.error("Submit error:", err);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = (text) => {
    navigator.clipboard.writeText(text).then(() => {
      console.log("Copied to clipboard");
    }).catch(err => {
      console.error("Failed to copy:", err);
    });
  };

  const downloadAsText = () => {
    if (!result) return;

    try {
      const content = result.points.join("\n");
      const blob = new Blob([content], { type: "text/plain" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = `resume-points-${result.repository_info.name || 'export'}.txt`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      console.log("File downloaded successfully");
    } catch (err) {
      console.error("Download failed:", err);
      setError("Failed to download file");
    }
  };

  // Load historical entry result into display
  const loadHistoryEntry = (entry) => {
    console.log("Loading history entry:", entry);

    setResult({
      points: entry.points,
      repository_info: entry.repository_info,
      processing_time: entry.timestamp
        ? entry.timestamp instanceof Date 
          ? entry.timestamp.toLocaleString()
          : new Date(entry.timestamp.seconds * 1000).toLocaleString()
        : "N/A",
    });

    // Optionally populate form with historical data
    if (entry.github_url) {
      setFormData(prev => ({
        ...prev,
        github_url: entry.github_url,
        branch: entry.branch || "",
        num_points: entry.settings?.num_points || prev.num_points,
        technical_level: entry.settings?.technical_level || prev.technical_level,
        output_tone: entry.settings?.output_tone || prev.output_tone,
        generate_technical: entry.settings?.generate_technical ?? prev.generate_technical
      }));
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-purple-900 to-slate-900">
      <div className="container mx-auto px-4 py-8 max-w-7xl grid grid-cols-1 lg:grid-cols-4 gap-6">

        {/* Sidebar - User Info + History */}
        <aside className="bg-white/10 backdrop-blur-lg rounded-2xl p-6 shadow-lg border border-white/20 max-h-[85vh] overflow-y-auto text-white">
          <div className="flex flex-col items-center mb-6">
            <div className="bg-purple-600 rounded-full h-16 w-16 flex items-center justify-center text-xl font-bold text-white mb-3">
              {user.displayName ? user.displayName[0] : "U"}
            </div>
            <h2 className="text-xl font-semibold text-center">
              {user.displayName || "User"}
            </h2>
            <p className="text-sm text-gray-300 text-center mt-1">
              {user.email}
            </p>
            <button
              onClick={handleLogout}
              className="mt-4 bg-red-600 hover:bg-red-700 px-4 py-2 rounded text-white w-full transition duration-200"
            >
              Logout
            </button>
          </div>

          <h3 className="font-bold mb-3 text-lg border-b border-white/30 pb-2">
            Previous Repos
          </h3>

          {historyLoading && (
            <div className="flex items-center justify-center py-4">
              <div className="animate-spin rounded-full h-6 w-6 border-b-2 border-white"></div>
              <span className="ml-2 text-sm">Loading history...</span>
            </div>
          )}

          {!historyLoading && history.length === 0 && (
            <p className="text-gray-300 text-sm">No history yet. Generate your first resume points!</p>
          )}

          <ul className="space-y-3 max-h-[60vh] overflow-y-auto">
            {history.map((entry, idx) => (
              <li
                key={entry.id || idx}
                onClick={() => loadHistoryEntry(entry)}
                className="cursor-pointer hover:bg-white/20 rounded p-3 transition duration-200 border border-white/10"
                title={entry.github_url}
              >
                <div className="font-semibold truncate text-sm">
                  {entry.repository_info?.name || entry.github_url?.split('/').pop() || 'Unknown Repo'}
                </div>
                <div className="text-xs text-gray-400 mt-1">
                  <div className="truncate">Branch: {entry.branch || "Auto-detected"}</div>
                  <div className="mt-1">
                    {entry.timestamp
                      ? entry.timestamp instanceof Date 
                        ? entry.timestamp.toLocaleDateString()
                        : new Date(entry.timestamp.seconds * 1000).toLocaleDateString()
                      : "N/A"}
                  </div>
                </div>
              </li>
            ))}
          </ul>
        </aside>

        {/* Main content - REST OF YOUR EXISTING CODE REMAINS THE SAME */}
        <main className="lg:col-span-3 bg-white/10 backdrop-blur-lg rounded-2xl p-8 shadow-2xl border border-white/20 max-h-[85vh] overflow-y-auto">
          {/* Header */}
          <div className="text-center mb-8">
            <div className="flex items-center justify-center mb-4">
              <Github className="text-white mr-3" size={40} />
              <Sparkles className="text-yellow-400 ml-2" size={32} />
            </div>
            <h1 className="text-4xl font-bold text-white mb-2">
              GitHub Resume Points Generator
            </h1>
            <p className="text-gray-300 text-lg">
              Transform your GitHub repositories into professional resume bullet points with smart branch detection
            </p>
          </div>

          {/* Form */}
          <div className="space-y-6">
            {/* GitHub URL Input */}
            <div>
              <label className="block text-white text-sm font-semibold mb-2">
                GitHub Repository URL
              </label>
              <div className="relative">
                <Github className="absolute left-3 top-3 text-gray-400" size={20} />
                <input
                  type="url"
                  name="github_url"
                  value={formData.github_url}
                  onChange={handleInputChange}
                  onBlur={handleUrlBlur}
                  placeholder="https://github.com/username/repository"
                  className="w-full pl-12 pr-4 py-3 bg-white/10 border border-white/20 rounded-lg text-white placeholder-gray-400 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                  required
                />
              </div>
              {loadingBranches && (
                <p className="text-sm text-gray-400 mt-1">Loading branches...</p>
              )}
            </div>

            {/* Branch Selection */}
            {branches.length > 0 && (
              <div>
                <label className="block text-white text-sm font-semibold mb-2 flex items-center">
                  <GitBranch className="mr-2" size={16} />
                  Branch (Optional - auto-detects best branch if empty)
                </label>
                <select
                  name="branch"
                  value={formData.branch}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                >
                  <option value="">Auto-detect best branch</option>
                  {branches.map((branch) => (
                    <option key={branch} value={branch} className="bg-gray-800">
                      {branch}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Settings Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div>
                <label className="block text-white text-sm font-semibold mb-2">
                  Number of Points
                </label>
                <input
                  type="number"
                  name="num_points"
                  value={formData.num_points}
                  onChange={handleInputChange}
                  min="1"
                  max="10"
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                />
              </div>

              <div>
                <label className="block text-white text-sm font-semibold mb-2">
                  Technical Level
                </label>
                <select
                  name="technical_level"
                  value={formData.technical_level}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                >
                  <option value="basic" className="bg-gray-800">Basic</option>
                  <option value="medium" className="bg-gray-800">Medium</option>
                  <option value="advanced" className="bg-gray-800">Advanced</option>
                </select>
              </div>

              <div>
                <label className="block text-white text-sm font-semibold mb-2">
                  Output Tone
                </label>
                <select
                  name="output_tone"
                  value={formData.output_tone}
                  onChange={handleInputChange}
                  className="w-full px-4 py-3 bg-white/10 border border-white/20 rounded-lg text-white focus:outline-none focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                >
                  <option value="concise" className="bg-gray-800">Concise</option>
                  <option value="detailed" className="bg-gray-800">Detailed</option>
                  <option value="action-oriented" className="bg-gray-800">Action-Oriented</option>
                </select>
              </div>

              <div className="flex items-center">
                <input
                  type="checkbox"
                  name="generate_technical"
                  checked={formData.generate_technical}
                  onChange={handleInputChange}
                  className="w-5 h-5 text-purple-600 bg-white/10 border-white/20 rounded focus:ring-purple-500"
                />
                <label className="ml-3 text-white text-sm font-semibold">
                  Focus on Technical Details
                </label>
              </div>
            </div>

            {/* Submit Button */}
            <button
              type="button"
              onClick={handleSubmit}
              disabled={loading || !formData.github_url}
              className="w-full bg-gradient-to-r from-purple-600 to-pink-600 hover:from-purple-700 hover:to-pink-700 disabled:opacity-50 disabled:cursor-not-allowed text-white font-bold py-4 px-6 rounded-lg transition duration-300 transform hover:scale-105 focus:outline-none focus:ring-2 focus:ring-purple-500 focus:ring-offset-2 focus:ring-offset-transparent"
            >
              {loading ? (
                <div className="flex items-center justify-center">
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white mr-2"></div>
                  Analyzing Repository & Generating Points...
                </div>
              ) : (
                <div className="flex items-center justify-center">
                  <Sparkles className="mr-2" size={20} />
                  Generate Enhanced Resume Points
                </div>
              )}
            </button>
          </div>

          {/* Error */}
          {error && (
            <div className="mt-6 p-4 bg-red-500/20 border border-red-500/30 rounded-lg">
              <p className="text-red-200 text-sm">{error}</p>
              <button 
                onClick={() => setError("")}
                className="mt-2 text-xs text-red-300 hover:text-red-100 underline"
              >
                Dismiss
              </button>
            </div>
          )}

          {/* Rest of your existing result display code remains the same */}
          {result && (
            <div className="mt-8 space-y-6">
              {/* Repository Info */}
              <div className="bg-white/5 rounded-lg p-6 border border-white/10">
                <h3 className="text-xl font-bold text-white mb-4 flex items-center">
                  <Github className="mr-2" size={24} />
                  {result.repository_info.name}
                </h3>
                <p className="text-gray-300 mb-4">{result.repository_info.description}</p>
                <div className="flex flex-wrap items-center gap-4 text-sm text-gray-400">
                  <div className="flex items-center">
                    <Star className="mr-1" size={16} />
                    {result.repository_info.stars} stars
                  </div>
                  <div className="flex items-center">
                    <GitFork className="mr-1" size={16} />
                    {result.repository_info.forks} forks
                  </div>
                  <div className="flex items-center">
                    <Clock className="mr-1" size={16} />
                    {result.processing_time || "N/A"}
                  </div>
                  <div className="flex items-center">
                    <GitBranch className="mr-1" size={16} />
                    {result.repository_info.branch_used || "main"}
                  </div>
                  <div className="bg-purple-600 px-2 py-1 rounded text-white text-xs">
                    {result.repository_info.language}
                  </div>
                </div>

                {result.repository_info.available_branches && result.repository_info.available_branches.length > 1 && (
                  <div className="mt-3 p-3 bg-blue-500/20 rounded-lg border border-blue-500/30">
                    <p className="text-blue-200 text-sm">
                      <GitBranch className="inline mr-1" size={14} />
                      Repository has {result.repository_info.available_branches.length} branches: {result.repository_info.available_branches.join(", ")}
                    </p>
                  </div>
                )}
              </div>

              {/* Resume Points */}
              <div className="bg-white/5 rounded-lg p-6 border border-white/10">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-xl font-bold text-white">Enhanced Resume Points</h3>
                  <div className="flex space-x-2">
                    <button
                      onClick={() => copyToClipboard(result.points.join("\n"))}
                      className="flex items-center px-3 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-lg transition duration-200"
                    >
                      <Copy className="mr-1" size={16} />
                      Copy All
                    </button>
                    <button
                      onClick={downloadAsText}
                      className="flex items-center px-3 py-2 bg-green-600 hover:bg-green-700 text-white rounded-lg transition duration-200"
                    >
                      <Download className="mr-1" size={16} />
                      Download
                    </button>
                  </div>
                </div>

                <div className="space-y-4">
                  {result.points.map((point, idx) => (
                    <div
                      key={idx}
                      className="flex items-start space-x-4 p-4 bg-white/5 rounded-lg border border-white/10 group hover:bg-white/10 transition duration-200"
                    >
                      <div className="flex-shrink-0 w-8 h-8 bg-gradient-to-r from-purple-600 to-pink-600 rounded-full flex items-center justify-center text-white text-sm font-bold">
                        {idx + 1}
                      </div>
                      <div className="flex-1">
                        <p className="text-gray-200 leading-relaxed text-base">{point}</p>
                      </div>
                      <button
                        onClick={() => copyToClipboard(point)}
                        className="opacity-0 group-hover:opacity-100 transition duration-200 p-2 hover:bg-white/10 rounded-lg"
                      >
                        <Copy className="text-gray-400 hover:text-white" size={16} />
                      </button>
                    </div>
                  ))}
                </div>
              </div>

              {/* Pro Tips */}
              <div className="bg-gradient-to-r from-blue-500/20 to-purple-500/20 rounded-lg p-6 border border-blue-500/30">
                <h4 className="text-lg font-semibold text-white mb-3">💡 Pro Tips for Using These Points:</h4>
                <ul className="text-gray-300 text-sm space-y-2">
                  <li>• Customize each point to match the specific job requirements</li>
                  <li>• Add quantifiable metrics where possible (e.g., "improved performance by 30%")</li>
                  <li>• Use these as starting points and expand with your specific contributions</li>
                  <li>• Adjust technical terminology based on your target audience</li>
                </ul>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default Dashboard;
